/**
 * Format that outputs CSS custom properties with auto-generated
 * text color tokens for each background
 */
import { getContrastRatio } from '../contrast-helpers.js';
import { contrastConfig } from '../../build.js';

export default {
  name: 'css/variables-with-contrast',
  format: async ({ dictionary, options }) => {
    const tokens = dictionary.allTokens;
    let output = '/**\n';
    output += ' * Design Tokens with Auto-Generated Contrast Colors\n';
    output += ' * Generated by Style Dictionary\n';
    output += ' * DO NOT EDIT DIRECTLY\n';
    output += ' */\n\n';
    output += ':root {\n';

    // Build a map of foreground tokens for quick lookup
    const foregroundTokens = {};
    tokens.forEach(token => {
      if (token.path[token.path.length - 1] === contrastConfig.foregroundTokenName) {
        const key = `${token.path[0]}.${token.path[1]}`;
        foregroundTokens[key] = token.value;
      }
    });

    tokens.forEach(token => {
      // Skip foreground tokens (they're metadata, not CSS variables)
      if (token.name.includes(`-${contrastConfig.foregroundTokenName}`) && !token.name.includes(`-${contrastConfig.backgroundTokenName}`)) {
        return;
      }

      // Output the original token
      output += `  --${token.name}: ${token.value};\n`;

      // If this token has contrast metadata, generate text color tokens
      if (token.attributes?.contrast) {
        const baseName = token.name.replace(`-${contrastConfig.backgroundTokenName}`, '');
        const { aa, aaa } = token.attributes.contrast;

        // Generate AA text color token
        output += `  --${baseName}-${contrastConfig.foregroundTokenName}-aa: ${aa.color}; /* ${aa.ratio}:1 */\n`;

        // Generate AAA text color token
        output += `  --${baseName}-${contrastConfig.foregroundTokenName}-aaa: ${aaa.color}; /* ${aaa.ratio}:1 */\n`;

        // If a foreground colour was chosen, output it as a CSS variable with compliance comment
        const componentGroup = token.path[0];
        const componentVariant = token.path[1];
        const foregroundKey = `${componentGroup}.${componentVariant}`;
        if (foregroundTokens[foregroundKey]) {
          const chosenForeground = foregroundTokens[foregroundKey];
          const chosenRatio = getContrastRatio(token.value, chosenForeground);
          const chosenStatus = chosenRatio >= 4.5 ? '✅' : '❌ fails';
          output += `  --${baseName}-${contrastConfig.foregroundTokenName}: ${chosenForeground}; /* chosen colour ${chosenStatus} ${chosenRatio.toFixed(2)}:1 */\n`;
        }

        // Add a warning comment if AAA doesn't pass
        if (!aaa.passes) {
          output += `  /* ⚠️  ${baseName} does not meet AAA standards (requires 7:1) */\n`;
        }

        output += '\n';
      }
    });

    output += '}\n';
    return output;
  }
};
